def generate_docs():
    """Write out all 37 topic pages and master index."""
    readme_lines = [
        "# RAGA: Technical Documentation & Systems Reference Manual",
        "",
        "Welcome to the official 37-chapter architectural and technical reference documentation for **RAGA** (Retrieval-Augmented Generation Agent with Context Compression & Semantic Memory).",
        "",
        "This documentation covers every facet of the RAGA engineering architecture: from foundational data structures, hybrid retrieval mechanics, and neural cross-encoder compression, to cognitive memory taxonomies, enterprise deployment patterns, and industry use cases.",
        "",
        "Each chapter is an in-depth, rigorous technical exposition designed for machine learning engineers, systems architects, and enterprise software developers.",
        "",
        "## Table of Contents",
        "",
    ]

    for topic in TOPICS_DATA:
        tid = topic["id"]
        title = topic["title"]
        paragraphs = topic["paragraphs"]

        # Assert exactly 7 medium paragraphs
        assert len(paragraphs) == 7, f"Topic {tid} must contain exactly 7 paragraphs, got {len(paragraphs)}"

        filename = f"topic_{tid:02d}.md"
        filepath = TOPICS_DIR / filename

        # Write topic markdown file
        md_content = [
            f"# Chapter {tid:02d}: {title}",
            "",
            "> Part of the **RAGA Architecture & Systems Engineering Reference Manual**.",
            "",
        ]

        for p in paragraphs:
            md_content.append(p)
            md_content.append("")

        filepath.write_text("\n".join(md_content), encoding="utf-8")
        readme_lines.append(f"- [Chapter {tid:02d}: {title}](topics/{filename})")

    readme_lines.append("")
    readme_lines.append("---")
    readme_lines.append("*Authored for RAGA by sayan-kundu000.*")

    (DOCS_DIR / "README.md").write_text("\n".join(readme_lines), encoding="utf-8")
    print(f"Successfully generated {len(TOPICS_DATA)} topic pages and docs/README.md!")

if __name__ == "__main__":
    generate_docs()

